const sections=["Товары","Данные","Настройки"],root=document.querySelector("#root");let active="Товары";function render(){root.innerHTML=`<div class="app-shell"><aside class="sidebar" aria-label="Основная навигация"><div class="brand">SCOZ</div><nav>${sections.map(s=>`<button type="button" class="nav-item ${s===active?"active":""}" ${s===active?'aria-current="page"':""}>${s}</button>`).join("")}</nav></aside><main class="main-content"><header><p class="eyebrow">Рабочее пространство</p><h1>${active}</h1></header><section class="empty-state"><h2>Раздел готов к работе</h2><p>Данные для этого раздела пока не загружены.</p></section></main></div>`;document.querySelectorAll(".nav-item").forEach((button,index)=>button.addEventListener("click",()=>{active=sections[index];render()}))}render();
